mapper.select:
SELECT er.id, er.evidence_no, er.work_title, er.work_desc, er.work_category, er.work_hash, er.tx_hash, er.block_number, er.evidence_time, er.verify_count, er.status, er.create_time, su.username as user_name, (SELECT COUNT(*) FROM work_file wf WHERE wf.evidence_id = er.id) as file_count FROM evidence_record er LEFT JOIN sys_user su ON er.user_id = su.id
AND (er.work_title LIKE CONCAT('%', #{keyword}, '%') OR er.evidence_no LIKE CONCAT('%', #{keyword}, '%'))
AND er.work_category = #{category}
AND er.status = #{status}
ORDER BY er.create_time DESC

SELECT er.id, er.evidence_no, er.work_title, er.work_desc, er.work_category, er.work_hash, er.tx_hash, er.block_number, er.evidence_time, er.verify_count, er.status, er.create_time, su.username as user_name, (SELECT COUNT(*) FROM work_file wf WHERE wf.evidence_id = er.id) as file_count FROM evidence_record er LEFT JOIN sys_user su ON er.user_id = su.id
AND er.user_id = #{userId}
AND (er.work_title LIKE CONCAT('%', #{keyword}, '%') OR er.evidence_no LIKE CONCAT('%', #{keyword}, '%'))
AND er.work_category = #{category}
AND er.status = #{status}
ORDER BY er.create_time DESC
